<?php
// Edit an organiser-owned event. Published events remain subject to admin approval rules.
require_once __DIR__ . '/shared-components/auth.php'; require_once __DIR__ . '/database-config/connection.php'; require_once __DIR__ . '/shared-components/functions.php';
if (session_status() !== PHP_SESSION_ACTIVE) session_start(); requireRole('organiser');
$user_id=(int)($_SESSION['UserID']??0); $event_id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT); if(!$event_id || !$user_id){http_response_code(400); exit('Invalid event request.');}
if(empty($_SESSION['csrf_token'])) $_SESSION['csrf_token']=bin2hex(random_bytes(32));
$q=$pdo->prepare('SELECT * FROM EVENTS WHERE EventID=:event AND OrganiserID=:uid LIMIT 1'); $q->execute(['event'=>$event_id,'uid'=>$user_id]); $event=$q->fetch(PDO::FETCH_ASSOC); if(!$event){http_response_code(404); exit('Event not found or you do not have permission to edit it.');}
$cat=$pdo->query('SELECT CategoryID, CategoryName FROM CATEGORIES ORDER BY CategoryName')->fetchAll(PDO::FETCH_ASSOC); $tq=$pdo->prepare('SELECT TicketID, TicketType, Price, QuantityAvailable, Capacity, Description FROM TICKETS WHERE EventID=:id ORDER BY TicketID'); $tq->execute(['id'=>$event_id]); $tickets=$tq->fetchAll(PDO::FETCH_ASSOC);
$errors=[];$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($_SESSION['csrf_token'],(string)($_POST['csrf_token']??'')))$errors[]='Invalid session token. Refresh and try again.';
 $name=trim((string)($_POST['EventName']??''));$description=trim((string)($_POST['Description']??''));$venue=trim((string)($_POST['Venue']??''));$province=trim((string)($_POST['Province']??''));$date_raw=trim((string)($_POST['EventDate']??''));$format=(string)($_POST['Format']??'');$category_id=filter_var($_POST['CategoryID']??null,FILTER_VALIDATE_INT);$age=trim((string)($_POST['AgeRestriction']??''));$hashtags=trim((string)($_POST['Hashtags']??''));$goal=(string)($_POST['CareerGoalType']??'none');$career=filter_var($_POST['AllowedCareerField']??null,FILTER_VALIDATE_INT);$domain=strtolower(trim((string)($_POST['AllowedEmailDomain']??'')));
 $dt=DateTime::createFromFormat('Y-m-d\TH:i',$date_raw); if(mb_strlen($name)<3||mb_strlen($name)>100)$errors[]='Event name must be 3–100 characters.';if(mb_strlen($description)>10000)$errors[]='Description is too long.';if(!$dt)$errors[]='Enter a valid event date and time.';if(!in_array($format,['online','physical','hybrid'],true))$errors[]='Invalid event format.';if(!$category_id||!in_array((int)$category_id,array_map(fn($c)=>(int)$c['CategoryID'],$cat),true))$errors[]='Select a valid category.';if(!in_array($goal,['none','field','email_domain'],true))$errors[]='Invalid eligibility option.';if($goal==='field'&&(!$career||!in_array((int)$career,array_map(fn($c)=>(int)$c['CategoryID'],$cat),true)))$errors[]='Select a valid eligible career field.';if($goal==='email_domain'&&!preg_match('/^[a-z0-9.-]+\.[a-z]{2,}$/i',$domain))$errors[]='Enter a valid email domain.';
 // Do not allow ticket capacity to fall below already-reserved/paid quantities.
 $ticket_inputs=$_POST['ticket']??[]; $validated=[];
 foreach($tickets as $ticket){$tid=(int)$ticket['TicketID'];$in=$ticket_inputs[$tid]??[];$price=trim((string)($in['price']??$ticket['Price']));$capacity=trim((string)($in['capacity']??$ticket['Capacity']));$desc=trim((string)($in['description']??$ticket['Description']));if(!is_numeric($price)||(float)$price<0||!preg_match('/^\d+$/',$capacity)||(int)$capacity<1){$errors[]='Ticket prices must be non-negative and capacities must be positive whole numbers.';continue;}$b=$pdo->prepare("SELECT COALESCE(SUM(Quantity),0) FROM BOOKINGS WHERE TicketID=:ticket AND Status IN ('pending','paid')");$b->execute(['ticket'=>$tid]);$reserved=(int)$b->fetchColumn();if((int)$capacity<$reserved)$errors[]='Capacity for '.$ticket['TicketType'].' cannot be lower than existing active booking quantities ('.$reserved.').';$validated[]=['id'=>$tid,'price'=>(float)$price,'capacity'=>(int)$capacity,'description'=>mb_substr($desc,0,255)];}
 if(!$errors){try{$pdo->beginTransaction();$up=$pdo->prepare("UPDATE EVENTS SET CategoryID=:category, EventName=:name, Description=:description, Venue=:venue, EventDate=:event_date, AgeRestriction=:age, Format=:format, Hashtags=:hashtags, CareerGoalType=:goal, AllowedCareerField=:career, AllowedEmailDomain=:domain, Province=:province WHERE EventID=:event AND OrganiserID=:uid");$up->execute(['category'=>(int)$category_id,'name'=>$name,'description'=>$description?:null,'venue'=>$venue?:null,'event_date'=>$dt->format('Y-m-d H:i:s'),'age'=>$age?:null,'format'=>$format,'hashtags'=>$hashtags?:null,'goal'=>$goal,'career'=>$goal==='field'?(int)$career:null,'domain'=>$goal==='email_domain'?$domain:null,'province'=>$province?:null,'event'=>$event_id,'uid'=>$user_id]);$tu=$pdo->prepare('UPDATE TICKETS SET Price=:price, Capacity=:capacity, QuantityAvailable=:available, Description=:description WHERE TicketID=:id AND EventID=:event');foreach($validated as $v){$old=$tickets[array_search($v['id'],array_column($tickets,'TicketID'))];$available=max(0,$v['capacity']-((int)$old['Capacity']-(int)$old['QuantityAvailable']));$tu->execute(['price'=>$v['price'],'capacity'=>$v['capacity'],'available'=>min($v['capacity'],$available),'description'=>$v['description']?:null,'id'=>$v['id'],'event'=>$event_id]);}$pdo->commit();$success='Event details saved.';$q->execute(['event'=>$event_id,'uid'=>$user_id]);$event=$q->fetch(PDO::FETCH_ASSOC);$tq->execute(['id'=>$event_id]);$tickets=$tq->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('EventNest edit-event failure: '.$e->getMessage());$errors[]='Could not save the event. Please try again.';}}
}
$page_title='Edit event';require_once __DIR__.'/shared-components/header.php';$date_value=date('Y-m-d\TH:i',strtotime($event['EventDate']));
?>
<main id="main-content" class="container form-page"><h1>Edit event</h1><p>Changes do not bypass EventNest event-approval or publication rules.</p><?php foreach($errors as $e):?><p class="alert alert-danger"><?=en_e($e)?></p><?php endforeach;?><?php if($success):?><p class="alert alert-success"><?=en_e($success)?></p><?php endif;?>
<form method="post" action="edit-event.php?id=<?=(int)$event_id?>"><input type="hidden" name="csrf_token" value="<?=en_e($_SESSION['csrf_token'])?>">
<label for="EventName">Event name</label><input id="EventName" name="EventName" maxlength="100" required value="<?=en_e($event['EventName'])?>"><label for="Description">Description</label><textarea id="Description" name="Description" maxlength="10000" rows="5"><?=en_e($event['Description']??'')?></textarea>
<label for="CategoryID">Category</label><select id="CategoryID" name="CategoryID" required><?php foreach($cat as $c):?><option value="<?=(int)$c['CategoryID']?>" <?=(int)$event['CategoryID']===(int)$c['CategoryID']?'selected':''?>><?=en_e($c['CategoryName'])?></option><?php endforeach;?></select><label for="Venue">Venue</label><input id="Venue" name="Venue" maxlength="150" value="<?=en_e($event['Venue']??'')?>"><label for="Province">Province</label><input id="Province" name="Province" maxlength="100" value="<?=en_e($event['Province']??'')?>"><label for="EventDate">Date and time</label><input id="EventDate" type="datetime-local" name="EventDate" required value="<?=en_e($date_value)?>"><label for="Format">Format</label><select id="Format" name="Format"><?php foreach(['physical'=>'In-person','online'=>'Online','hybrid'=>'Hybrid'] as $v=>$label):?><option value="<?=en_e($v)?>" <?=$event['Format']===$v?'selected':''?>><?=en_e($label)?></option><?php endforeach;?></select>
<label for="AgeRestriction">Age restriction</label><select id="AgeRestriction" name="AgeRestriction"><option value="">None</option><option value="18+" <?=($event['AgeRestriction']??'')==='18+'?'selected':''?>>18+</option><option value="21+" <?=($event['AgeRestriction']??'')==='21+'?'selected':''?>>21+</option></select><label for="Hashtags">Public hashtags</label><input id="Hashtags" name="Hashtags" maxlength="255" value="<?=en_e($event['Hashtags']??'')?>"><label for="CareerGoalType">Eligibility</label><select id="CareerGoalType" name="CareerGoalType"><?php foreach(['none'=>'No additional gate','field'=>'Career field','email_domain'=>'Email domain'] as $v=>$label):?><option value="<?=en_e($v)?>" <?=$event['CareerGoalType']===$v?'selected':''?>><?=en_e($label)?></option><?php endforeach;?></select><label for="AllowedCareerField">Allowed career field</label><select id="AllowedCareerField" name="AllowedCareerField"><option value="">Select</option><?php foreach($cat as $c):?><option value="<?=(int)$c['CategoryID']?>" <?=(int)($event['AllowedCareerField']??0)===(int)$c['CategoryID']?'selected':''?>><?=en_e($c['CategoryName'])?></option><?php endforeach;?></select><label for="AllowedEmailDomain">Allowed email domain (without @)</label><input id="AllowedEmailDomain" name="AllowedEmailDomain" maxlength="100" value="<?=en_e($event['AllowedEmailDomain']??'')?>">
<h2>Ticket tiers</h2><?php foreach($tickets as $t):?><fieldset><legend><?=en_e($t['TicketType'])?></legend><label for="p<?=(int)$t['TicketID']?>">Price (R)</label><input id="p<?=(int)$t['TicketID']?>" type="number" min="0" step="0.01" name="ticket[<?=(int)$t['TicketID']?>][price]" value="<?=en_e($t['Price'])?>"><label for="c<?=(int)$t['TicketID']?>">Capacity</label><input id="c<?=(int)$t['TicketID']?>" type="number" min="1" step="1" name="ticket[<?=(int)$t['TicketID']?>][capacity]" value="<?=en_e($t['Capacity'])?>"><label for="d<?=(int)$t['TicketID']?>">Description</label><input id="d<?=(int)$t['TicketID']?>" maxlength="255" name="ticket[<?=(int)$t['TicketID']?>][description]" value="<?=en_e($t['Description']??'')?>"></fieldset><?php endforeach;?>
<button class="btn btn-primary" type="submit">Save changes</button> <a class="btn btn-outline" href="user-dashboard.php">Cancel</a></form></main><?php require_once __DIR__.'/shared-components/footer.php';?>
